   "titolo": "Cgil in piazza a Roma, Landini annuncia sciopero generale il 20 novembre",
   "orig": "Cgil in piazza: 'Siamo 100mila, il 20 novembre sciopero generale'",
   "lead": "La Cgil ha portato in piazza a Roma circa 100mila persone, secondo il sindacato, annunciando uno sciopero generale per il 20 novembre. Il segretario Maurizio Landini ha chiesto al governo di smettere con le \"marchette elettorali\" e di dare risposte concrete nella manovra economica, incluso un intervento di patrimoniale. Lo riferisce ANSA.",
   "more": [
    "Lo sciopero generale annunciato arriva in un periodo di scontro tra sindacati e governo sulla legge di bilancio, con la Cgil che da mesi chiede misure fiscali più eque e maggiori investimenti sociali."
   ],
