   "titolo": "I commercianti cinesi del Sud-est asiatico sotto pressione dalla concorrenza cinese",
   "orig": "Southeast Asia’s ethnic Chinese traders feel the China squeeze",
   "lead": "I commercianti di etnia cinese nel Sud-est asiatico, come l'imprenditore indonesiano Kevin Stewart, segnalano una crescente pressione competitiva da parte di aziende cinesi che vendono direttamente ai loro stessi clienti, talvolta a prezzi inferiori. Il fenomeno si inserisce nell'espansione del commercio elettronico cinese nella regione, che sta mettendo in difficoltà gli intermediari locali. Lo riferisce South China Morning Post.",
   "more": [
    "Le piattaforme e-commerce cinesi hanno ampliato la propria presenza nel Sud-est asiatico, permettendo ai produttori cinesi di raggiungere direttamente i consumatori locali, riducendo il ruolo tradizionale degli intermediari della diaspora cinese."
   ],
