   "id": "zeedd01dc",
   "sez": "ambiente",
   "titolo": "L'Indonesia usa ghiaccio secco contro la foschia a South Sumatra",
   "orig": "Indonesia drops 2.4 tonnes of dry ice over South Sumatra to tackle haze",
   "lead": "L'Indonesia ha sganciato 2,4 tonnellate di ghiaccio secco sulla provincia di South Sumatra per contrastare la foschia causata dagli incendi boschivi e agricoli. La provincia è una delle sei aree prioritarie individuate dal governo indonesiano per la prevenzione e la gestione degli incendi. Lo riferisce CNA.",
   "more": [
    "La tecnica del seeding con ghiaccio secco viene usata per indurre pioggia artificiale, favorendo le precipitazioni che aiutano a spegnere gli incendi e disperdere il fumo tossico che ogni anno colpisce il Sud-est asiatico."
   ],
