   "id": "zc06614f5",
   "sez": "cultura",
   "titolo": "Per imparare una lingua, meglio concentrarsi sui suoni che sulla grammatica",
   "orig": "Stop making sense: focus on sounds to help learn a language, study suggests",
   "lead": "Un nuovo studio suggerisce che per imparare davvero bene una lingua straniera come francese, arabo o ungherese sia più efficace concentrarsi sui suoni piuttosto che memorizzare vocabolario e grammatica. La ricerca ha scoperto che i cervelli dei linguisti più talentuosi percepiscono i suoni delle lingue straniere più come rumore che come parole. Lo riferisce The Guardian.",
   "more": [
    "L'apprendimento fonologico, cioè la capacità di distinguere suoni non familiari, è considerato da tempo un fattore chiave nell'acquisizione linguistica, poiché permette di cogliere le sottigliezze sonore prima di passare alla comprensione del significato."
   ],
