   "sez": "mondo",
   "titolo": "Nel Regno Unito calano ma restano lunghi i tempi di attesa per l'esame di guida",
   "orig": "Driving test waits fall to two-year low - but still average 20 weeks",
   "lead": "I tempi di attesa per l'esame di guida pratico nel Regno Unito sono scesi al minimo degli ultimi due anni, ma restano comunque alti, con una media di 19,7 settimane a settembre, circa cinque mesi. Il dato segna un miglioramento rispetto ai picchi precedenti, ma il problema delle lunghe liste d'attesa per i candidati automobilisti persiste. Lo riferisce BBC News.",
   "more": [
    "Le lunghe attese per gli esami di guida nel Regno Unito sono state attribuite in parte all'arretrato accumulato durante la pandemia di Covid-19, con le autorità britanniche che da anni cercano di ridurre i tempi d'attesa per i candidati."
   ],
