   "titolo": "Grottaferrata celebra i 150 anni dalla nascita di Massimo Bontempelli",
   "orig": "A 150 anni dalla nascita del maestro Massimo Bontempelli, Grottaferrata celebra il Realismo Magico con un convegno internazionale",
   "lead": "Grottaferrata celebrerà i 150 anni dalla nascita dello scrittore Massimo Bontempelli con un convegno internazionale il 22 e 23 ottobre, promosso dal Centro Studi \"Massimo Bontempelli\" ETS. L'evento riunirà studiosi italiani e internazionali, scrittori, filosofi, artisti ed esperti di cinema per discutere l'eredità del Realismo Magico e la sua attualità. Lo riferisce Rai News.",
   "more": [
    "Massimo Bontempelli è stato uno scrittore e intellettuale italiano del Novecento, considerato tra i principali teorici del Realismo Magico, corrente letteraria che mescola elementi fantastici e quotidiani nella narrazione."
   ],
