   "id": "zdffec543",
   "sez": "ambiente",
   "titolo": "Alle Fiji i droni monitorano la siccità nelle piantagioni di canna da zucchero",
   "orig": "Drones track drought threat to sugarcane",
   "lead": "La Fiji Sugar Corporation sta utilizzando drammi, immagini satellitari e mappatura digitale delle aziende agricole per individuare precocemente lo stress da siccità nelle coltivazioni di canna da zucchero. La tecnologia permetterà di migliorare le previsioni sulla produzione e fornire informazioni più accurate ad agricoltori, governo e industria dello zucchero. Lo riferisce FBC News.",
   "more": [
    "Le Fiji dipendono fortemente dall'industria della canna da zucchero per l'economia rurale, e i cambiamenti climatici con periodi di siccità più frequenti minacciano la produttività agricola dell'arcipelago del Pacifico."
   ],
