   "id": "zf99795b1",
   "sez": "spazio",
   "titolo": "L'Ucraina chiede accesso al sistema satellitare militare americano Starshield",
   "orig": "Ukrajna hozzáférést kért a Starshield amerikai katonai műholdas kommunikációs rendszerhez",
   "lead": "L'Ucraina ha richiesto di poter accedere al sistema di comunicazione satellitare militare statunitense Starshield, versione militare del servizio internet commerciale Starlink, entrambi di proprietà di SpaceX, l'azienda di Elon Musk. La richiesta arriva nel contesto del conflitto in corso con la Russia, dove le comunicazioni satellitari sicure rivestono un ruolo strategico fondamentale per le operazioni militari ucraine. Lo riferisce Telex English.",
   "more": [
    "Starlink è già stato ampiamente utilizzato dalle forze ucraine per garantire connettività sul campo di battaglia dall'inizio dell'invasione russa nel 2022. Starshield, la variante militare del sistema, offre maggiori garanzie di sicurezza e resistenza alle interferenze, risultando particolarmente utile per comunicazioni criptate e operazioni di difesa."
   ],
