   "titolo": "Giappone, nuove linee guida del ministero della Salute per gli spot pubblicitari in film e tv",
   "orig": "Japan’s health ministry sets new guidelines for tie-up ads in movies and TV shows",
   "lead": "Il ministero della Salute giapponese ha stabilito nuove linee guida per le pubblicità promozionali inserite in film e programmi televisivi. La decisione è stata presa dopo che un poster di sostegno ai malati di cancro, realizzato dal ministero in collaborazione con un film, aveva suscitato critiche sui social media. Lo riferisce The Japan Times.",
