   "orig": "Special exhibition to offer rare glimpse at ancient Egyptian mummies",
   "lead": "Una mostra speciale a Seul offrirà al pubblico una rara occasione di vedere mummie egizie antiche, tra cui una coppia di mummie di gatto e una statua in pietra calcarea. L'esposizione punta a far conoscere reperti dell'antico Egitto raramente visibili al pubblico coreano. Lo riferisce Yonhap.",
