   "id": "za12cae37",
   "sez": "sport",
   "titolo": "Cricket, la scarsa luce nel primo Test Sudafrica-Australia riaccende il dibattito sulla palla rosa",
   "orig": "COLOUR COORDINATION: Bad light in the first Proteas-Aussies Test reignites the pink ball debate",
   "lead": "Le prime tre giornate del primo Test tra Sudafrica e Australia sono state segnate da problemi di luce scarsa, riaccendendo la discussione tra giocatori e addetti ai lavori sull'uso della palla rossa o di quella rosa nei match a cinque giorni. La questione, già dibattuta in passato nel cricket internazionale, torna quindi al centro delle polemiche dopo l'incontro. Lo riferisce Daily Maverick.",
   "more": [
    "La palla rosa è stata introdotta nei Test disputati con luci artificiali o in orari serali, perché più visibile della tradizionale palla rossa al tramonto, ma il suo comportamento in campo è spesso oggetto di critiche da parte dei giocatori."
   ],
