   "lead": "L'artista tessile britannica Kate Jenkins ha allestito a Londra un'installazione intitolata 'Kate's Knitalian', un ristorante italiano in cui ogni elemento, dai piatti agli arredi, è realizzato interamente a maglia. L'opera gioca sull'illusione, invitando i visitatori a scoprire che nulla, in quello spazio apparentemente realistico, è come sembra a prima vista. Lo riferisce Wallpaper*.",
