   "sez": "italia",
   "titolo": "Roma, giovane investito da un treno della metro: è gravissimo",
   "orig": "Roma, caos e paura in metro: giovane investito dal treno della linea A. «Estratto ancora vivo, è gravissimo»",
   "lead": "Un ragazzo di 28 anni è stato investito ieri pomeriggio da un treno della linea A della metropolitana di Roma, alla stazione Baldo degli Ubaldi. Il giovane è rimasto coinvolto sotto il convoglio, scatenando momenti di caos e paura tra i passeggeri presenti sulla banchina. È stato estratto ancora vivo ma le sue condizioni sono state definite gravissime dai soccorritori intervenuti sul posto. Lo riferisce Il Messaggero.",
