   "titolo": "Moldova, il mercato elettrico diventa riferimento per i prezzi all'ingrosso",
   "orig": "Expert: The electricity market in Moldova becomes a benchmark for wholesale prices",
   "lead": "Il volume di energia elettrica scambiato sul mercato del giorno prima in Moldova è aumentato da 2,2 GWh nel giugno scorso a 87 GWh nel settembre 2026, diventando secondo un esperto un parametro di riferimento sempre più rilevante per i prezzi all'ingrosso dell'energia nel paese. La crescita segnala una maggiore liquidità e partecipazione degli operatori al mercato elettrico nazionale. Lo riferisce IPN.",
   "more": [
    "I mercati elettrici 'day-ahead' permettono a produttori e consumatori di negoziare energia per il giorno successivo, e una maggiore liquidità in genere rende i prezzi più trasparenti e rappresentativi delle condizioni reali di domanda e offerta."
   ],
