   "titolo": "Il regista Tsukamoto Shin'ya racconta la guerra del Vietnam nel film su Allen Nelson",
   "orig": "“Mr. Nelson, Did You Kill People?”: Filmmaker Tsukamoto Shin’ya Uses Vietnam to Deliver a Visceral Warning",
   "lead": "Il regista giapponese Tsukamoto Shin'ya ha realizzato il film 'Mr. Nelson, Did You Kill People?', dedicato alla storia di Allen Nelson, veterano statunitense della guerra del Vietnam che ha trascorso decenni parlando pubblicamente delle sue esperienze belliche e del trauma post-bellico. L'opera intende offrire un monito viscerale sulla violenza della guerra attraverso la testimonianza personale del protagonista. Lo riferisce Nippon.com.",
   "more": [
    "Allen Nelson fu un marine statunitense che combatté in Vietnam e divenne poi attivista pacifista, raccontando pubblicamente in Giappone e altrove le atrocità vissute e commesse durante il conflitto, fino alla sua morte nel 2009."
   ],
