   "titolo": "Stagione 2026 deludente per i giocatori sudcoreani in MLB",
   "orig": "Korean MLB players saw a disappointing 2026 season",
   "lead": "La stagione 2026 di baseball nella Major League statunitense ha portato risultati contrastanti per i giocatori sudcoreani, con diversi atleti alle prese con difficoltà a ottenere un ruolo stabile in squadra o a soddisfare le aspettative. Lee Jung-hoo è stato il più costante tra i sudcoreani, con 143 partite giocate, una media battuta di .276, 10 fuoricampo, 57 punti battuti a casa e un OPS di .724, migliorando rispetto alla stagione precedente ma con un rendimento meno regolare nella seconda parte dell'anno. Lo riferisce The Korea Herald.",
