   "sez": "ambiente",
   "titolo": "In Europa cresce la moda dei vialetti solari per sfruttare ogni superficie soleggiata",
   "orig": "‘Every sunny surface’ is being put to work. Europeans transforming their homes with solar driveways",
   "lead": "Sempre più europei stanno trasformando le proprie abitazioni installando pannelli solari anche su vialetti e superfici inutilizzate, nel tentativo di sfruttare ogni spazio esposto al sole. L'iniziativa viene presentata come un contributo individuale verso un sistema energetico più economico, sicuro e di proprietà diretta dei cittadini, in linea con gli obiettivi europei di transizione energetica domestica. Lo riferisce Euronews.",
   "more": [
    "La diffusione di impianti fotovoltaici residenziali in Europa è cresciuta negli ultimi anni grazie alla riduzione dei costi delle tecnologie solari e agli incentivi pubblici, spingendo i cittadini a installare pannelli anche su superfici non convenzionali oltre ai tetti."
   ],
