   "lead": "Lo studio B.E. Architecture ha progettato a Melbourne 'Casa Piva', un'abitazione minimalista costruita attorno a una sequenza di cortili nascosti pensati per garantire privacy e isolamento dagli sguardi esterni. Il progetto si sviluppa attraverso spazi generosi ma riservati, pensati per offrire tranquillità ai residenti nonostante la posizione urbana. Lo riferisce Wallpaper*.",
