   "sez": "salute",
   "titolo": "Un supporto finanziario personalizzato riduce lo stress economico nei malati di cancro",
   "orig": "Patient-centered financial navigation assistance helps reduce financial toxicity among cancer patients",
   "lead": "Un servizio di assistenza nella navigazione finanziaria centrato sul paziente aiuta a ridurre quella che i ricercatori chiamano 'tossicità finanziaria' tra i malati di cancro, cioè l'impatto economico dei costi elevati delle cure oncologiche. Questo peso finanziario spinge spesso i pazienti ad adottare comportamenti dannosi, come ritardare o rinunciare ai trattamenti e saltare l'assunzione di farmaci prescritti. Lo riferisce Medical Xpress.",
   "more": [
    "La tossicità finanziaria è un concetto usato in ambito oncologico per descrivere lo stress economico causato dai costi delle cure, che negli Stati Uniti comprendono spesso spese elevate non coperte interamente dalle assicurazioni sanitarie."
   ],
