   "titolo": "Mauritius prolunga il coprifuoco fino a domenica dopo le violenze",
   "orig": "OCÉAN INDIEN – Maurice prolonge le couvre-feu jusqu’à dimanche après des violences",
   "lead": "Il governo di Mauritius ha prolungato fino a domenica il coprifuoco notturno imposto su circa un terzo dell'isola principale, dopo giorni di manifestazioni contro la carenza d'acqua e il caro vita, seguite da episodi di violenza. Dalla sera di lunedì sono state arrestate circa 150 persone. La circolazione notturna resta limitata in alcune località. Lo riferisce 2424.mg.",
   "more": [
    "Mauritius, piccolo stato insulare dell'Oceano Indiano noto per stabilità politica e turismo, ha recentemente conosciuto tensioni sociali legate al rincaro dei prezzi e a problemi infrastrutturali come la gestione delle risorse idriche, mettendo sotto pressione il governo."
   ],
