   "id": "z101d73f8",
   "sez": "prima",
   "titolo": "Carovita, le proteste degenerano in guerriglia a Milano: decine di feriti",
   "orig": "Le proteste per il carovita diventate guerriglia: scontri e feriti a Milano",
   "lead": "Le manifestazioni contro il carovita organizzate dagli \"autoconvocati\" sono sfociate in violenti scontri nel centro di Milano, con negozi saccheggiati e circa quaranta persone portate in ospedale. La polizia ha effettuato cariche di alleggerimento contro i manifestanti, che hanno risposto con sassi e bombe carta. Decine di persone, molte giovanissime, sono state condotte in questura. Disordini simili si sono registrati anche a Torino e Bologna, in una giornata di tensione diffusa in diverse città italiane. Lo riferisce la Repubblica.",
   "more": [
    "Le proteste per il carovita nascono dal malcontento legato all'aumento del costo della vita, in particolare dei beni di prima necessità e degli affitti, che colpisce soprattutto le fasce più giovani e precarie della popolazione italiana. Gli \"autoconvocati\" sono gruppi spontanei non legati a organizzazioni tradizionali."
   ],
